const PRONUNCIATIONS = {};

const allowIndex = buildAllowIndex(ALLOWED);
const noStore = { get: async () => null, set: async () => {} };
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.pathname !== '/api/tts') return env.ASSETS.fetch(request);
    const cache = typeof caches !== 'undefined' ? caches.default : null;
    if (cache) { try { const hit = await cache.match(request); if (hit) return hit; } catch (e) { /* cache is optional */ } }
    const res = await handle(request, { store: noStore, fetchFn: fetch, env, allowIndex, pronunciations: PRONUNCIATIONS });
    if (cache && res.status === 200) ctx.waitUntil(cache.put(request, res.clone()).catch(() => {}));
    return res;
  }
};
